data_contract.config:

return [
    'resources' => [
        'request-management' => [
            // Deep-link del record, usato per costruire action_url delle notifiche.
            'record_path' => '/request-management',
            // Chiave i18n del modulo, mostrata come "dominio/modulo di appartenenza".
            'label' => 'navigation.requestManagement',
            'fields' => [
                'source_id' => [
                    // permesso generato: "{resource}.{ability}" = request-management.updateSource
                    'ability' => 'updateSource',
                    // id colonna della TableDefinition, per applicare via updateCell()
                    'column'  => 'source',
                    // chiave i18n del campo, mostrata come "campo oggetto della modifica"
                    'label'   => 'requestManagement.columns.source',
                ],
            ],
        ],
    ],
];

endpoint.response:
 { "success": true, "message": "Change request approved", "data": <FieldChangeRequestResource> } 
`status: "approved"`, `handled_by`, `handled_at`, `handling_note` valorizzati, `pending_key` a NULL.
Il valore e' gia' stato applicato al record nella STESSA transazione (D-7).

data_contract.contract_extension:

{
  "id": "source",
  "editable": true,
  "editableField": "source_id",
  "change_request": {                       // NUOVO: presente SOLO quando la colonna e' protetta
    "resource": "request-management",       // e l'attore non ha il permesso di scriverla.
    "field": "source_id"                    // Il client intercetta il commit e apre il dialog
  }                                         // invece di eseguire il PATCH (D-2).
}


// Ai titolari di field-change-requests.viewAny, escluso il richiedente:
{ "title": "Nuova richiesta di modifica",
  "message": "<Richiedente> chiede di cambiare <campo> di <record> da <attuale> a <richiesto>",
  "level": "info",
  "action_url": "/field-change-requests/<id>" }

// Al richiedente, alla decisione (D-3):
{ "title": "Richiesta di modifica approvata|rifiutata",
  "message": "<Gestore> ha <esito> la tua richiesta su <campo> di <record>[. Nota: <nota>]",
  "level": "success|warning",
  "action_url": "/request-management/<subject_id>" }
